import {chromium} from 'playwright';
import assert from 'node:assert/strict';
function samplePdf(){const txt='BT /F1 30 Tf 70 710 Td (PARTITURES FESTERES PROVA) Tj ET';const o=['<</Type/Catalog/Pages 2 0 R>>','<</Type/Pages/Kids[3 0 R]/Count 1>>','<</Type/Page/Parent 2 0 R/MediaBox[0 0 600 800]/Resources<</Font<</F1 5 0 R>>>>/Contents 4 0 R>>','<</Length '+txt.length+'>>\nstream\n'+txt+'\nendstream','<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>'];let out='%PDF-1.4\n',offsets=[];for(let i=0;i<o.length;i++){offsets.push(out.length);out+=(i+1)+' 0 obj\n'+o[i]+'\nendobj\n'}const xref=out.length;out+='xref\n0 '+(o.length+1)+'\n0000000000 65535 f \n';for(const offset of offsets)out+=String(offset).padStart(10,'0')+' 00000 n \n';out+='trailer\n<</Root 1 0 R/Size '+(o.length+1)+'>>\nstartxref\n'+xref+'\n%%EOF\n';return Buffer.from(out,'ascii')}
const b=await chromium.launch({headless:true,args:['--no-sandbox']});try{const c=await b.newContext({viewport:{width:390,height:844},deviceScaleFactor:2});const p=await c.newPage(),errors=[];p.on('pageerror',e=>errors.push(String(e)));await p.goto('http://127.0.0.1:8765/');if(await p.locator('[data-action="welcome-done"]').count())await p.locator('[data-action="welcome-done"]').click();await p.locator('#import-input').setInputFiles({name:'PROVA.pdf',mimeType:'application/pdf',buffer:samplePdf()});await p.locator('[data-action="open"]').first().waitFor();await p.locator('[data-action="open"]').first().click();await p.locator('.viewer-canvas').waitFor({timeout:30000});assert.equal(await p.locator('.viewer-frame').count(),0);const w=await p.locator('.viewer-canvas').evaluate(x=>x.width);assert(w>100);await p.locator('[data-action="viewer-zoom-in"]').click();await p.waitForFunction(()=>document.querySelector('#viewer-zoom-label')?.textContent==='120%');await p.locator('[data-action="viewer-rotate"]').click();await p.waitForFunction(()=>{const c=document.querySelector('.viewer-canvas');return c&&c.width>c.height});await p.locator('[data-action="viewer-close"]').click();await p.locator('[data-action="open"]').first().click();await p.locator('.viewer-canvas').waitFor({timeout:30000});assert.equal(await p.locator('#viewer-zoom-label').textContent(),'120%');assert.deepEqual(errors,[]);console.log('PASS: PDF canvas, zoom, rotate, persistence');await c.close()}finally{await b.close()}
